/**
 * Extraction-backed tier. Fixtures are real binary files generated by
 * scripts/generate_extraction_fixtures.py; raw reads show opaque bytes and the
 * agent must discover how to work with them using its default tools.
 *
 * Prompts deliberately name no utility, library, or installation step.
 */

import type { SuiteSpec, WorkspaceCheck } from "../../src/config.ts";

const exists = (path: string): WorkspaceCheck => ({ op: "exists", path });

function assets(group: string, paths: readonly string[]): Record<string, string> {
	return Object.fromEntries(paths.map((path) => [path, `fixtures/extraction/${group}/${path}`]));
}

